//! ⏱️ The genuine continuation effect uses original funded text and exact native argument rows.
use super::*;
use flow::FlowTextCopyWork;
use semio_plugin::Effect;
#[derive(RetireOwned)]
struct Fields{texts:[Option<String>;5],rows:Vec<(String,DslValue)>,output:Option<Effect>}
pub(crate) struct FlowTickEffectWork{fields:ManuallyDrop<Option<Fields>>,text:Option<FlowTextCopyWork>,retirement:RetainedCloneClose,binding:Option<(OriginalSourceBinding,usize,usize,usize,usize)>,rank:usize,phase:u8,closing:bool}
impl FlowTickEffectWork{
 pub(crate) fn new()->Self{Self{fields:ManuallyDrop::new(Some(Fields{texts:[None,None,None,None,None],rows:Vec::new(),output:None})),text:None,retirement:Default::default(),binding:None,rank:0,phase:0,closing:false}}
 pub(crate) fn step(&mut self,window:&str,kind:&str,cx:&mut StepContext<'_>)->Result<Option<Effect>,OriginalTurnFailure>{for _ in 0..512{let before=(cx.retained_progress(),cx.original_total_fuel_remaining());if let Some(value)=self.once(window,kind,cx)?{return Ok(Some(value))}if cx.should_yield()||cx.is_cancelled()||before==(cx.retained_progress(),cx.original_total_fuel_remaining()){break}}Ok(None)}
 fn once(&mut self,window:&str,kind:&str,cx:&mut StepContext<'_>)->Result<Option<Effect>,OriginalTurnFailure>{
  let binding=(OriginalSourceBinding::borrow(cx),window.as_ptr()as usize,window.len(),kind.as_ptr()as usize,kind.len());if self.closing||self.binding.is_some_and(|original|original!=binding){return Err(invalid().into())}if cx.should_yield()||cx.is_cancelled(){return Ok(None)}
  match self.phase{
   0=>if super::origin::paid(cx,size_of::<FlowTextCopyWork>()+size_of::<Option<(OriginalSourceBinding,usize,usize,usize,usize)>>())?{self.binding=Some(binding);self.text=Some(FlowTextCopyWork::new());self.phase=1},
   1=>{let source=match self.rank{0=>"flowEvalTick",1=>"windowId",2=>"windowKindId",3=>window,4=>kind,_=>return Err(invalid().into())};let text=self.text.as_mut().ok_or_else(invalid)?;if !text.ready(){text.advance(source,cx)?;}else if text.take_into(&mut self.fields.as_mut().ok_or_else(invalid)?.texts[self.rank],cx)?{text.begin_close();self.phase=2}},
   2=>{let text=self.text.as_mut().ok_or_else(invalid)?;if text.terminal_is_empty(){if super::origin::paid(cx,size_of::<FlowTextCopyWork>())?{self.text=None;self.rank+=1;self.phase=if self.rank==5{3}else{0}}}else{let d=text.close_demands(cx.retained_grant().maximum_copy_bytes)?;close_original_retained_step(cx,d,|g|text.close_step(g))?;}},
   3=>{let fields=self.fields.as_mut().ok_or_else(invalid)?;let d=RetirementDemand{capacity_bytes:2*size_of::<(String,DslValue)>(),depth:1,..Default::default()};if !cx.retained_work_can_enter(d){return Ok(None)}fields.rows.try_reserve_exact(2).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"original tick argument reservation refused"))?;self.phase=4;cx.consume_fuel(1);cx.consume_retained(RetainedCloneProgress{copied_items:1,retained_capacity_bytes:fields.rows.capacity()*size_of::<(String,DslValue)>(),..Default::default()})?;},
   4|5=>if super::origin::paid(cx,2*size_of::<(String,DslValue)>())?{let fields=self.fields.as_mut().ok_or_else(invalid)?;let(key,value)=if self.phase==4{(1,3)}else{(2,4)};fields.rows.push((fields.texts[key].take().ok_or_else(invalid)?,DslValue::String(fields.texts[value].take().ok_or_else(invalid)?)));self.phase+=1},
   6=>if super::origin::paid(cx,2*size_of::<Effect>())?{let fields=self.fields.as_mut().ok_or_else(invalid)?;fields.output=Some(Effect::DispatchAction{req:semio_plugin::RequestId(super::super::super::flow_eval_tick::FLOW_EVAL_HOP_REQUEST),action:fields.texts[0].take().ok_or_else(invalid)?,args:Some(DslValue::Object(std::mem::take(&mut fields.rows))),delay_ms:0});self.phase=7},
   7=>if super::origin::paid(cx,2*size_of::<Option<Effect>>())?{self.phase=8;return Ok(self.fields.as_mut().ok_or_else(invalid)?.output.take())},
   _=>return Err(invalid().into())
  }Ok(None)
 }
 pub(crate) fn restore_output(&mut self,value:Effect){assert_eq!(self.phase,8);self.fields.as_mut().expect("original tick fields").output=Some(value);self.phase=7}
 pub(crate) fn begin_close(&mut self){self.closing=true;if let Some(text)=self.text.as_mut(){text.begin_close()}}
 pub(crate) fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if let Some(text)=self.text.as_ref(){return if text.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<FlowTextCopyWork>(),depth:1,..Default::default()})}else{text.close_demands(body)}}if !self.retirement.is_empty(){return self.retirement.demands(body)}if self.fields.is_some(){return self.retirement.next_owner_demands::<Fields>(true,&None,body)}Ok(RetirementDemand{copy_bytes:size_of::<Option<(OriginalSourceBinding,usize,usize,usize,usize)>>(),depth:usize::from(self.binding.is_some()),..Default::default()})}
 pub(crate) fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<Close,OriginalTurnFailure>{if !self.closing||self.binding.is_some_and(|binding|!binding.0.matches(cx)){return Err(invalid().into())}if let Some(text)=self.text.as_mut(){if !text.terminal_is_empty(){let d=text.close_demands(cx.retained_grant().maximum_copy_bytes)?;let step=close_original_retained_step(cx,d,|g|text.close_step(g))?;return Ok(Close::Pending{progress:step.progress()})}let d=RetirementDemand{copy_bytes:size_of::<FlowTextCopyWork>(),depth:1,..Default::default()};if cx.retirement_should_yield()||!cx.retained_work_can_enter(d){return Ok(Close::Blocked)}self.text=None;cx.consume_fuel(1);let p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};cx.consume_retained(p)?;return Ok(Close::Pending{progress:p})}
  let d=self.close_demands(cx.retained_grant().maximum_copy_bytes)?;let step=close_original_retained_step(cx,d,|g|{if !self.retirement.is_empty(){return self.retirement.step_granted(g)}if self.fields.is_some(){let turn=self.retirement.begin_granted(&mut self.fields,g);return RetainedWorkOutcome{result:turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))),work:turn.work}}if self.binding.is_none(){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}if !retained_clone_grant_admits(g,d){return RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0}}self.binding=None;RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})),work:1}})?;Ok(if self.terminal_is_empty(){Close::Complete{progress:step.progress()}}else{Close::Pending{progress:step.progress()}})}
 pub(crate) fn terminal_is_empty(&self)->bool{self.closing&&self.text.is_none()&&self.fields.is_none()&&self.retirement.is_empty()&&self.binding.is_none()}
}
impl Drop for FlowTickEffectWork{fn drop(&mut self){assert!(self.terminal_is_empty(),"original continuation effect and text require paid terminal closure");unsafe{ManuallyDrop::drop(&mut self.fields)}}}
